/**
 * Embedded CAEPI database (Brazilian Ministry of Labor registry of approved PPE).
 *
 * `issuedOn` is the publication date of the source file (ISO format).
 * `compressedBase64` is a gzip-compressed JSON document encoded as Base64.
 * The decoded JSON has the shape:
 *   { r: number[], n: string[], d: string[], s: string[], em: string }
 * where `r` holds groups of four numbers per certificate
 * [caNumberDelta, nameIndex, validityIndex, situationIndex] and `n`, `d`, `s`
 * are lookup tables for equipment names, validity dates and situations.
 * See scripts/features/settings/caepi-database.js for the decoder.
 */
export const EMBEDDED_CAEPI = {
  issuedOn: '2026-10-12',
  compressedBase64:
    '',
};
